1	export type Item = {
2	  type: string;
3	  cursed?: boolean;
4	  enchantment?: number;
5	};
6	
7	export type Customer = {
8	  yearsWithMHPCO: number;
9	};
10	
11	export type Scenario = {
12	  customer: Customer;
13	  steps: { op: string; items: Item[] }[];
14	};
15	
16	export type ScenarioResult = {
17	  results: { premium: number }[];
18	};
19	
20	const PROCESSING_FEE = 5;
21	
22	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
23	
24	const BASE_PREMIUMS: Record<string, number> = {
25	  sword: 100,
26	  amulet: 60,
27	  staff: 80,
28	  potion: 40,
29	  rune: 25,
30	  moonstone: 25,
31	};
32	
33	// Every percentage modifier is a delta computed against an *unmodified* base
34	// and summed with the others — modifiers never compound. Policy-wide ones use
35	// the policy base, item-specific ones the affected item's own base premium.
36	//
37	// Percentages stay in integer percent points: multiply first, divide by 100
38	// last. A float multiplier such as `base * 1.1` yields 110.00000000000001 for
39	// a sword and breaks the ceil. `(base * 10) / 100` gives exactly 10.
40	const percentOf = (amount: number, percent: number): number =>
41	  (amount * percent) / 100;
42	
43	const BLOCK_SIZE = 3;
44	const BLOCK_BASE_PREMIUM = 60;
45	
46	const countByType = (items: Item[]): Map<string, number> => {
47	  const counts = new Map<string, number>();
48	
49	  for (const item of items) {
50	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
51	  }
52	
53	  return counts;
54	};
55	
56	const baseOfGroup = (type: string, count: number): number =>
57	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
58	
59	const policyBaseOf = (items: Item[]): number =>
60	  [...countByType(items)].reduce(
61	    (total, [type, count]) => total + baseOfGroup(type, count),
62	    0,
63	  );
64	
65	// A modifier rule: when `applies` holds for the subject, `percent` percent of
66	// the relevant base premium is added. A negative percent is a discount. Every
67	// rule whose predicate holds contributes; the deltas are summed, never
68	// compounded.
69	type ModifierRule<Subject> = {
70	  applies: (subject: Subject) => boolean;
71	  percent: number;
72	};
73	
74	const sumApplicablePercents = <Subject>(
75	  rules: ModifierRule<Subject>[],
76	  subject: Subject,
77	): number =>
78	  rules.reduce(
79	    (total, rule) => (rule.applies(subject) ? total + rule.percent : total),
80	    0,
81	  );
82	
83	// Policy-wide modifiers: each is a percentage of the policy base premium.
84	//
85	// Their subject is the *policy* — the circumstances under which this quote is
86	// issued — not the customer alone. Today those circumstances are just who is
87	// asking; rules that also depend on where the quote sits in the scenario read
88	// the field they need off the same subject.
89	type Policy = {
90	  customer: Customer;
91	  // Zero-based ordinal among the customer's quotes in this scenario.
92	  quoteOrdinal: number;
93	};
94	
95	const LOYALTY_YEARS_THRESHOLD = 2;
96	const LOYALTY_DISCOUNT_PERCENT = -20;
97	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = -15;
98	
99	const POLICY_MODIFIER_RULES: ModifierRule<Policy>[] = [
100	  { applies: () => true, percent: FIRST_INSURANCE_SURCHARGE_PERCENT },
101	  {
102	    applies: ({ customer }) =>
103	      customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
104	    percent: LOYALTY_DISCOUNT_PERCENT,
105	  },
106	  {
107	    applies: ({ quoteOrdinal }) => quoteOrdinal > 0,
108	    percent: FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT,
109	  },
110	];
111	
112	const policyModifierDelta = (policyBase: number, policy: Policy): number =>
113	  percentOf(policyBase, sumApplicablePercents(POLICY_MODIFIER_RULES, policy));
114	
115	// Item-specific modifiers: each is a percentage of the affected item's own
116	// base premium.
117	const CURSE_SURCHARGE_PERCENT = 50;
118	const HIGH_ENCHANTMENT_THRESHOLD = 5;
119	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
120	
121	const ITEM_MODIFIER_RULES: ModifierRule<Item>[] = [
122	  { applies: (item) => item.cursed === true, percent: CURSE_SURCHARGE_PERCENT },
123	  {
124	    applies: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
125	    percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT,
126	  },
127	];
128	
129	const itemModifierDelta = (item: Item): number =>
130	  percentOf(
131	    BASE_PREMIUMS[item.type],
132	    sumApplicablePercents(ITEM_MODIFIER_RULES, item),
133	  );
134	
135	const quote = (items: Item[], policy: Policy): number => {
136	  const policyBase = policyBaseOf(items);
137	  const modifiers =
138	    policyModifierDelta(policyBase, policy) +
139	    items.reduce((total, item) => total + itemModifierDelta(item), 0);
140	
141	  // Rounding is in the MHPCO's favour: premiums round up.
142	  return Math.ceil(policyBase + modifiers) + PROCESSING_FEE;
143	};
144	
145	export const runScenario = (scenario: Scenario): ScenarioResult => {
146	  let quoteOrdinal = 0;
147	
148	  const results = scenario.steps.map((step) => ({
149	    premium: quote(step.items, {
150	      customer: scenario.customer,
151	      quoteOrdinal: quoteOrdinal++,
152	    }),
153	  }));
154	
155	  return { results };
156	};
